import uuid

from fastapi import FastAPI, Request
from fastapi.testclient import TestClient


def test_request_id_header_present_when_enabled() -> None:
    app = FastAPI(add_request_id_header=True)

    @app.get("/ping")
    def ping() -> dict[str, str]:
        return {"pong": "ok"}

    client = TestClient(app)
    response = client.get("/ping")

    assert response.status_code == 200
    assert "X-Request-ID" in response.headers


def test_request_id_header_is_valid_uuid4() -> None:
    app = FastAPI(add_request_id_header=True)

    @app.get("/ping")
    def ping() -> dict[str, str]:
        return {"pong": "ok"}

    client = TestClient(app)
    response = client.get("/ping")

    request_id = response.headers["X-Request-ID"]
    parsed = uuid.UUID(request_id)
    assert parsed.version == 4


def test_request_id_header_absent_when_disabled() -> None:
    app = FastAPI()

    @app.get("/ping")
    def ping() -> dict[str, str]:
        return {"pong": "ok"}

    client = TestClient(app)
    response = client.get("/ping")

    assert "X-Request-ID" not in response.headers


def test_request_id_unique_per_request() -> None:
    app = FastAPI(add_request_id_header=True)

    @app.get("/ping")
    def ping() -> dict[str, str]:
        return {"pong": "ok"}

    client = TestClient(app)
    first = client.get("/ping").headers["X-Request-ID"]
    second = client.get("/ping").headers["X-Request-ID"]

    assert first != second


